arguments.command:
cd /tmp/friends-monica && git config user.name; git config user.email; echo "---"; cat > /tmp/askpass.sh <<'EOF'
#!/bin/sh
case "$1" in
  *[Uu]sername*) printf '%s' "x-access-token" ;;
  *[Pp]assword*) printf '%s' "$GITHUB_TOKEN" ;;
  *) printf '%s' "" ;;
esac
EOF
chmod +x /tmp/askpass.sh && echo askpass-ready
